/* Signature Turkmen Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Aysenem": "From ay (moon) + senem (idol/beloved).", "Serdargul": "From serdar (commander) + gul (flower): 'commander flower'.", "Merdanay": "From merdan (brave) + ay (moon): 'brave moon'.", "Guneshgul": "From gunesh (sun) + gul (flower): 'sun flower'.", "Batyrjan": "From batyr (hero) + jan (soul): 'hero soul'.", "Maraljan": "From maral (deer) + jan (soul).", "Aygulyev": "Signature surname in Turkmen -ev style built on Aygul.", "Serdarov": "Signature surname in -ov style built on Serdar.", "Merdangulyev": "Signature surname combining merdan + gul in -ev style.", "Guneshov": "Signature surname in -ov style built on gunesh (sun)."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Aysenem';
console.log(lookup(q));

